 ('LIS_REASON_CODE', 'REASON CODE', 2, 'ZERO_GAUCHE', 0, 'ALPHA', TRUE, FALSE, 'CREDIT :  00=NON SPECIFIE  05=REMISE COMMERCANT ACHAT  16=CHARGEBACK DE CREDIT VOUCHER  26=REDRESSEMENT CREDIT VOUCHER  35=REDRESSEMENT CHARGEBACK ACHAT  70=REDRESSEMENT DE FRAIS  75=PAIMENT DIFFERE DU COMMERÇANT  80=REMBOURSEMENT DE FRAIS DE LOCATION TPE  81=REDRESSEMENT DE FRAIS DE DOMMAGE TPE  82=REDRESSEMENT DE FRAIS DE REPARATION OU DE MAINTENANCE DE TPE  83=FRAIS DE SAISIE DE CARTE PAR LE COMMERCANT  84=REDRESSEMENT DES FRAIS D’ADHESION  86=REDRESSEMENT DE FRAIS DE GESTION DE CHARGEBACK  87=REDRESSEMENT DES FRAS ANNUELS  88=REDRESSEMENT DS FRAIS DE RELEVE SUPPLEMENTAIRE  89=REDRESSEMENT DE FRAIS DE RECHERCHE  91=REDRESSEMENT DE FRAIS DE FAR SUPPLEMENTAIRE  92=REDRESSEMENT DE FRAIS DE GESTION DE DEMANDE DE COPIE  19=REJET PAR VISA OU MASTERCARD DE CREDIT VOUCHER A CREDITER AU COMMERCANT  38=REJET PAR VISA OU MASTERCARD DE REDRESSEMENT DE TRANSACTION A CREDITER AU COMMERCANT  07 = POUR LE CASH-ADVANCE. DEBIT :  06=REMISE CREDIT VOUCHER  15=CHARGEBACK ACHAT  '),
